/**
 * Token-styled scrollbar for a region that already scrolls (`design/components/scroll-area.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/scroll-area.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, type JSX } from 'solid-js'

import * as zag from '@zag-js/scroll-area'
import { normalizeProps } from '@zag-js/solid'

import {
  claimSlot,
  classes,
  createDerived,
  elementRef,
  mergeParts,
  scope,
  useDirection,
  useMachine,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/scroll-area.module.css'

export type ScrollAreaOrientation = NonNullable<ScrollAreaProps['orientation']>

export type ScrollAreaType = NonNullable<ScrollAreaProps['type']>

export interface ScrollAreaProps {
  /**
   * The region's content; the consumer sets the region's *size* (a Table port's width, a panel's
   * height), and ScrollArea fills the box it is given.
   */
  children: JSX.Element
  /**
   * Names the region for keyboard users once it overflows, as in CodeBlock. Required rather than
   * defaulted. The content identifies the region, but a default name would be in one fixed
   * language, and the app's language is unknown here.
   */
  label: string
  /**
   * Which axes may pan; `'both'` draws two rails and the corner.
   */
  orientation?: 'horizontal' | 'vertical' | 'both'
  type?: 'hover' | 'always'
}

/** Token-styled scrollbar for a region that already scrolls. */
export default function ScrollArea(given: ScrollAreaProps): JSX.Element {
  const props = mergeProps(
    { orientation: 'vertical', type: 'always' } as Defaults<
      ScrollAreaProps,
      'orientation' | 'type'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const root = elementRef<HTMLElement>()
    const fades = createDerived(() => props.type === 'hover')
    const documentDirection = useDirection(() => root.value)
    const service = useMachine(
      zag.machine,
      () => ({ id: uid, dir: documentDirection() }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const overflowing = createDerived(() => api.value.hasOverflowX || api.value.hasOverflowY)
    return (
      <div
        {...mergeParts(api.value.getRootProps(), {
          class: styles.root,
          'data-member': 'scroll-area',
        })}
        ref={root.attach}
      >
        <div
          {...mergeParts(api.value.getViewportProps(), {
            class: styles.viewport,
            style: {
              'overflow-x': props.orientation === 'vertical' ? 'hidden' : 'scroll',
              'overflow-y': props.orientation === 'horizontal' ? 'hidden' : 'scroll',
              'scrollbar-width': 'none',
            },
            tabindex: overflowing.value ? 0 : undefined,
            role: overflowing.value ? 'region' : undefined,
            'aria-label': overflowing.value ? props.label : undefined,
          })}
        >
          <div {...mergeParts(api.value.getContentProps())}>{props.children}</div>
        </div>
        {props.orientation === 'both' || props.orientation === 'vertical' ? (
          api.value.hasOverflowY ? (
            <div
              {...mergeParts(api.value.getScrollbarProps({ orientation: 'vertical' }), {
                class: classes(
                  styles.rail,
                  fades.value ? styles.hover : undefined,
                  !fades.value ? styles.always : undefined,
                ),
                'aria-hidden': 'true',
                'data-state': fades.value
                  ? api.value.getScrollbarState({ orientation: 'vertical' }).hovering ||
                    api.value.getScrollbarState({ orientation: 'vertical' }).scrolling
                    ? 'visible'
                    : 'hidden'
                  : undefined,
              })}
            >
              <div
                {...mergeParts(api.value.getThumbProps({ orientation: 'vertical' }), {
                  class: styles.thumb,
                })}
              />
            </div>
          ) : null
        ) : null}
        {props.orientation === 'both' || props.orientation === 'horizontal' ? (
          api.value.hasOverflowX ? (
            <div
              {...mergeParts(api.value.getScrollbarProps({ orientation: 'horizontal' }), {
                class: classes(
                  styles.rail,
                  fades.value ? styles.hover : undefined,
                  !fades.value ? styles.always : undefined,
                ),
                'aria-hidden': 'true',
                'data-state': fades.value
                  ? api.value.getScrollbarState({ orientation: 'horizontal' }).hovering ||
                    api.value.getScrollbarState({ orientation: 'horizontal' }).scrolling
                    ? 'visible'
                    : 'hidden'
                  : undefined,
              })}
            >
              <div
                {...mergeParts(api.value.getThumbProps({ orientation: 'horizontal' }), {
                  class: styles.thumb,
                })}
              />
            </div>
          ) : null
        ) : null}
        {props.orientation === 'both' ? (
          <div
            {...mergeParts(api.value.getCornerProps(), {
              class: styles.corner,
              'aria-hidden': 'true',
            })}
          />
        ) : null}
      </div>
    )
  })
}
